import { readFile, open } from 'node:fs/promises'
import { z } from 'zod'
import { openDatabase } from '../dist/config/database.js'
import {
  inspectCatalogRollout,
  applyCatalogRollout,
} from '../dist/modules/catalog/catalog-rollout.service.js'

// Default is read-only. Approval records stay private and are never generated by this tool.
const approvalSchema = z.strictObject({
  environment: z.literal('staging'),
  databaseName: z.string().min(1).max(63),
  planDigest: z.string().regex(/^[a-f0-9]{64}$/),
  approvedBy: z.string().trim().min(1).max(200),
  approvedAt: z.iso.datetime({ offset: true }),
  validUntil: z.iso.datetime({ offset: true }),
  backupReference: z.string().trim().min(1).max(1000),
  maintenanceReference: z.string().trim().min(1).max(1000),
})
let connection
try {
  const args = process.argv.slice(2)
  const apply = args[0] === '--apply'
  if ((!apply && args.length !== 1) || (apply && args.length !== 3))
    throw new Error('Use <report-path> or --apply <approval-path> <report-path>.')
  const report = args[apply ? 2 : 0]
  const config = z
    .object({
      APP_ENV: z.literal('staging'),
      MONGODB_URI: z.string().regex(/^mongodb(?:\+srv)?:\/\/[^\s]+$/),
      MONGODB_DB_NAME: z.string().regex(/^[a-z][a-z0-9_]{0,62}$/),
    })
    .parse(process.env)
  if (config.APP_ENV !== 'staging' || !config.MONGODB_DB_NAME.endsWith('_staging'))
    throw new Error('Explicit isolated staging target required.')
  if (
    apply &&
    Object.entries(process.env).some(([key, value]) => key.endsWith('_ENABLED') && value === 'true')
  )
    throw new Error('Pause feature admission before applying a catalog rollout.')
  const approval = apply
    ? approvalSchema.parse(JSON.parse(await readFile(args[1], 'utf8')))
    : undefined
  if (
    approval &&
    (approval.databaseName !== config.MONGODB_DB_NAME ||
      Date.parse(approval.approvedAt) > Date.now() ||
      Date.parse(approval.validUntil) <= Date.now() ||
      Date.parse(approval.validUntil) <= Date.parse(approval.approvedAt))
  )
    throw new Error('Approval does not cover the target/current review window.')
  // Reserve an unused report path before any possible database mutation.
  const reportFile = await open(report, 'wx', 0o600)
  try {
    connection = await openDatabase(config.MONGODB_URI, config.MONGODB_DB_NAME)
    const result = approval
      ? await applyCatalogRollout(connection, approval.planDigest)
      : await inspectCatalogRollout(connection)
    await reportFile.writeFile(`${JSON.stringify(result, null, 2)}\n`)
    console.log(
      approval
        ? 'Catalog rollout verified; private report written.'
        : 'Read-only catalog report written.',
    )
    if (!result.safeToApply) process.exitCode = 1
  } catch {
    await reportFile.writeFile(
      '{"status":"failed","reason":"protected_preflight_or_rollout_failed"}\n',
    )
    throw new Error('Protected catalog operation failed.')
  } finally {
    await reportFile.close()
  }
} catch {
  // Deliberately exclude driver diagnostics, URIs, credentials and approval contents.
  console.error(
    'Staging catalog check failed; inspect protected access, target, plan and approval.',
  )
  process.exitCode = 1
} finally {
  await connection?.close()
}
